<?php
require_once __DIR__.'/includes/db.php';if(current_user())redirect('index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if(mb_strlen($name)<2||mb_strlen($name)>100)$error='Tên phải từ 2 đến 100 ký tự.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Email không hợp lệ.';elseif(strlen($pw)<10)$error='Mật khẩu cần tối thiểu 10 ký tự.';else try{$s=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'user')");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);flash('Tạo tài khoản thành công. Hãy đăng nhập.');redirect('login.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'Email này đã được đăng ký.':'Không thể tạo tài khoản lúc này.';}}$pageTitle='Đăng ký | HENDY';require __DIR__.'/includes/header.php';?><div class="auth-wrap"><form class="auth-card" method="post"><div class="eyebrow">JOIN HENDY</div><h1>Tạo tài khoản</h1><p class="muted">Đăng ký để sử dụng tiện ích thành viên.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Họ và tên</label><input name="name" maxlength="100" required autocomplete="name"><label>Email</label><input type="email" name="email" required autocomplete="email"><label>Mật khẩu (ít nhất 10 ký tự)</label><input type="password" name="password" minlength="10" required autocomplete="new-password"><button class="button primary full">Tạo tài khoản</button><p class="auth-foot">Đã có tài khoản? <a href="login.php">Đăng nhập</a></p></form></div><?php require __DIR__.'/includes/footer.php';?>